frappe.ui.form.on('Fees', {
    refresh: function(frm) {
        frm.add_custom_button(__('Add Discount'), function(){
        let d = new frappe.ui.Dialog({
        title: 'Add Discount',
        fields: [
            {
                label: 'Discount Name',
                fieldname: 'discount_name',
                fieldtype: 'Link',
                options: "Discount Configuration",
                get_query: function () {
    					return {
    						doctype: 'Discount Configuration',
    						filters: {
    							fee_structure: frm.doc.fee_structure,
    						},
    					};
				    }
            }
        ],
        size: 'large',
        primary_action_label: 'Submit',
        primary_action(values) {
            console.log(values);
            d.hide();
        }
    });

    d.show();

    }, __("Discount"));
    frm.add_custom_button(__('Remove Discount'), function(){
        frappe.msgprint(frm.doc.student_name);
    }, __("Discount"));
  }
});

frappe.ui.form.on('Fees', {
    refresh: function(frm) {
        if (frappe.session.user == "Administrator"){
             if (frm.doc.custom_authorized === 0){
                frm.remove_custom_button('Payment Request', 'Create')
                frm.add_custom_button(__('Authorize'), function(){
                    frappe.db.set_value("Fees", frm.doc.name, "custom_authorized", 1)
                    frappe.db.commit()
                    frm.remove_custom_button(__('Authorize'))
                    frm.add_custom_button('Payment Request', 'Create')
              });
            }
        }
    }
});

frappe.ui.form.on('Program Enrollment', {
	program: function(frm) {
		frm.set_query("custom_payment_plan", function() {
        return {
            "filters": {
                "program": frm.doc.program
            }
        };
    });
        frm.set_query("fee_structure","fees", function() {
            return {
                filters: [
                    ['Fee Structure','academic_term', '=', frm.doc.academic_term],
                    ['Fee Structure','program', '=', frm.doc.program]
                ]
            };
        });
    }
});

